package io.github.rebrowser.authority;

import static org.junit.Assert.*;
import io.github.rebrowser.control.*;
import io.github.rebrowser.crypto.CryptoEncoding;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;

public class DelegationAndPossessionTest {
 static final String BACK="host.window.back",OPEN="host.openDefaultBrowserFlow";
 static class L {
  final CurrentAuthorityKernelTest.F f=new CurrentAuthorityKernelTest.F();final KeyPair child=CurrentAuthorityKernelTest.key(),grand=CurrentAuthorityKernelTest.key();final AtomicLong utc=new AtomicLong(100);
  final LowDelegationVerifier verifier=new LowDelegationVerifier(f.compiled,f.target,f.epoch,utc::get);
  L()throws Exception{}
  LowDelegationVerifier.Certificate cert(String issuer,String id,int level,byte[] key,byte[] parent,String...actions){return new LowDelegationVerifier.Certificate(issuer,id,level,0,1000,key,parent,Arrays.asList(actions));}
  byte[] one(LowDelegationVerifier.Certificate c,PrivateKey issuer)throws Exception{byte[] b=verifier.signingBytes(c);return LowDelegationVerifier.encodeChain(Collections.singletonList(b),Collections.singletonList(CurrentAuthorityKernelTest.sign(issuer,b)));}
  byte[] two(String secondAction,int level,byte[] parentOverride)throws Exception{byte[] a=verifier.signingBytes(cert("root","child",3,child.getPublic().getEncoded(),new byte[32],BACK));byte[] b=verifier.signingBytes(cert("child","grand",level,grand.getPublic().getEncoded(),parentOverride==null?CryptoEncoding.sha256(a):parentOverride,secondAction));return LowDelegationVerifier.encodeChain(Arrays.asList(a,b),Arrays.asList(CurrentAuthorityKernelTest.sign(f.root.getPrivate(),a),CurrentAuthorityKernelTest.sign(child.getPrivate(),b)));}
 }
 @Test public void compiledRootDoesNotImplicitlyAuthorizeDelegation()throws Exception{L l=new L();CompiledPrincipals table=new CompiledPrincipals(new CompiledPrincipals.Entry("root",CompiledPrincipals.Role.ROOT,10,l.f.root.getPublic().getEncoded()));LowDelegationVerifier v=new LowDelegationVerifier(table,new byte[32],new byte[16],()->100);byte[] body=v.signingBytes(l.cert("root","child",2,l.child.getPublic().getEncoded(),new byte[32],BACK));byte[] chain=LowDelegationVerifier.encodeChain(Collections.singletonList(body),Collections.singletonList(CurrentAuthorityKernelTest.sign(l.f.root.getPrivate(),body)));assertThrows(GeneralSecurityException.class,()->v.verify(chain));}
 @Test public void compiledDelegationScopeCannotBeBroadenedByCertificate()throws Exception{L l=new L();CompiledPrincipals table=new CompiledPrincipals(new CompiledPrincipals.Entry("root",CompiledPrincipals.Role.ROOT,10,l.f.root.getPublic().getEncoded(),2,Collections.singleton(BACK)));LowDelegationVerifier v=new LowDelegationVerifier(table,new byte[32],new byte[16],()->100);for(String action:Arrays.asList(BACK,OPEN)){byte[] body=v.signingBytes(l.cert("root","child",3,l.child.getPublic().getEncoded(),new byte[32],action));byte[] chain=LowDelegationVerifier.encodeChain(Collections.singletonList(body),Collections.singletonList(CurrentAuthorityKernelTest.sign(l.f.root.getPrivate(),body)));assertThrows(GeneralSecurityException.class,()->v.verify(chain));}}
 @Test public void staticDelegationFieldsAreBoundedAndCommittedInPolicy()throws Exception{L l=new L();assertThrows(IllegalArgumentException.class,()->new CompiledPrincipals.Entry("root",CompiledPrincipals.Role.ROOT,10,l.f.root.getPublic().getEncoded(),5,Collections.singleton(BACK)));CompiledPrincipals other=new CompiledPrincipals(new CompiledPrincipals.Entry("root",CompiledPrincipals.Role.ROOT,10,l.f.root.getPublic().getEncoded(),2,Collections.singleton(BACK)),l.f.compiled.find("high"),l.f.compiled.find("low"));assertFalse(Arrays.equals(other.identityPolicySha256(),l.f.compiled.identityPolicySha256()));}
 @Test public void chainVerifiesRealSignaturesAndNarrowsAuthority()throws Exception{L l=new L();byte[] chain=l.two(BACK,2,null);LowDelegationVerifier.LeafProof p=l.verifier.verify(chain);assertArrayEquals(CryptoEncoding.sha256(chain),p.chainSha256());assertEquals("grand",p.keyId());assertEquals(2,p.ceiling());assertTrue(p.permits(BACK));assertFalse(p.permits(OPEN));byte[] request={1,2,3};assertTrue(p.verifyRequestBytes(request,CurrentAuthorityKernelTest.sign(l.grand.getPrivate(),request)));}
 @Test public void unconfiguredTableNeverAcceptsDelegation()throws Exception{L l=new L();LowDelegationVerifier v=new LowDelegationVerifier(CompiledPrincipals.production(),new byte[32],new byte[16],()->100);assertThrows(GeneralSecurityException.class,()->v.verify(l.two(BACK,2,null)));}
 @Test public void childCannotExpandActionScope()throws Exception{L l=new L();assertThrows(GeneralSecurityException.class,()->l.verifier.verify(l.two(OPEN,2,null)));}
 @Test public void childCannotRaiseParentCeiling()throws Exception{L l=new L();assertThrows(GeneralSecurityException.class,()->l.verifier.verify(l.two(BACK,4,null)));}
 @Test public void certificateCannotCreateHighIdentity()throws Exception{L l=new L();assertThrows(IllegalArgumentException.class,()->l.cert("root","child",5,l.child.getPublic().getEncoded(),new byte[32],BACK));}
 @Test public void chainCannotSpliceDifferentParent()throws Exception{L l=new L();assertThrows(GeneralSecurityException.class,()->l.verifier.verify(l.two(BACK,2,new byte[32])));}
 @Test public void childCannotAliasCompiledKey()throws Exception{L l=new L();assertThrows(GeneralSecurityException.class,()->l.verifier.verify(l.one(l.cert("root","child",3,l.f.high.getPublic().getEncoded(),new byte[32],BACK),l.f.root.getPrivate())));}
 @Test public void sameIdAsCompiledIdentityRejects()throws Exception{L l=new L();assertThrows(GeneralSecurityException.class,()->l.verifier.verify(l.one(l.cert("root","high",3,l.child.getPublic().getEncoded(),new byte[32],BACK),l.f.root.getPrivate())));}
 @Test public void wrongSigningPrivateKeyRejects()throws Exception{L l=new L();assertThrows(GeneralSecurityException.class,()->l.verifier.verify(l.one(l.cert("root","child",3,l.child.getPublic().getEncoded(),new byte[32],BACK),l.child.getPrivate())));}
 @Test public void utcDeadlineExactAndRollbackPermanentlyRejects()throws Exception{L l=new L();byte[] c=l.two(BACK,2,null);l.verifier.verify(c);l.utc.set(99);assertThrows(GeneralSecurityException.class,()->l.verifier.verify(c));l.utc.set(100);assertThrows(GeneralSecurityException.class,()->l.verifier.verify(c));L e=new L();e.utc.set(1000);assertThrows(GeneralSecurityException.class,()->e.verifier.verify(e.two(BACK,2,null)));}
 @Test public void boundedCodecRejectsTrailingBytesEmptyAndExcessDepth()throws Exception{L l=new L();byte[] c=l.two(BACK,2,null);assertThrows(GeneralSecurityException.class,()->l.verifier.verify(Arrays.copyOf(c,c.length+1)));assertThrows(GeneralSecurityException.class,()->l.verifier.verify(new byte[8193]));assertThrows(GeneralSecurityException.class,()->l.verifier.verify(new byte[]{5}));assertThrows(GeneralSecurityException.class,()->l.verifier.verify(new byte[]{0}));}
 @Test public void duplicateActionsUnknownActionsAndLongValidityReject()throws Exception{L l=new L();assertThrows(IllegalArgumentException.class,()->l.cert("root","child",2,l.child.getPublic().getEncoded(),new byte[32],BACK,BACK));assertThrows(IllegalArgumentException.class,()->l.cert("root","child",2,l.child.getPublic().getEncoded(),new byte[32],"mail.query"));assertThrows(IllegalArgumentException.class,()->new LowDelegationVerifier.Certificate("root","child",2,0,86_400_001,l.child.getPublic().getEncoded(),new byte[32],Collections.singleton(BACK)));}
 static class P {
  final CurrentAuthorityKernelTest.F f=new CurrentAuthorityKernelTest.F();final KeyPair device=CurrentAuthorityKernelTest.key();final byte[] target=CryptoEncoding.sha256(device.getPublic().getEncoded());final DeviceWhitelist whitelist;final TargetPossessionProof proofs;
  P(String owner)throws Exception{whitelist=new DeviceWhitelist(f.compiled,new DeviceWhitelist.Device(owner,device.getPublic().getEncoded()));proofs=new TargetPossessionProof(whitelist,f.pin,target,f.time::get);}
  AdminProofVerifier.KeyProof request(String principal)throws Exception{ControlChallengeStore s=new ControlChallengeStore(new ControlChallengeStore.Context(target,f.epoch,ActionRegistry.policySha256(f.compiled),0),f.time::get,4,4);ControlEnvelope frame=s.issue(new ControlChallengeStore.Template(principal,BACK,"win_00000000000000000000000000000000","",new byte[16],new byte[32],"{\"windowRef\":\"win_00000000000000000000000000000000\",\"expectedPresentationRevision\":0}".getBytes(StandardCharsets.UTF_8)));return f.decode(frame,principal.equals("root")?f.root.getPrivate():f.high.getPrivate());}
 }
 @Test public void actualTargetSignatureProducesSingleUseExactRequestReceipt()throws Exception{P p=new P("high");AdminProofVerifier.KeyProof request=p.request("high");TargetPossessionProof.Challenge c=p.proofs.issue(request);TargetPossessionProof.Receipt r=p.proofs.verify(c,CurrentAuthorityKernelTest.sign(p.device.getPrivate(),c.signingBytes()));p.proofs.consume(r,request);assertThrows(SecurityException.class,()->p.proofs.consume(r,request));assertThrows(SecurityException.class,()->p.proofs.verify(c,CurrentAuthorityKernelTest.sign(p.device.getPrivate(),c.signingBytes())));}
 @Test public void ordinaryHighestCannotBorrowRootsListButRootMayUseHighest()throws Exception{P p=new P("root");assertThrows(SecurityException.class,()->p.proofs.issue(p.request("high")));P q=new P("high");TargetPossessionProof.Challenge c=q.proofs.issue(q.request("root"));assertNotNull(q.proofs.verify(c,CurrentAuthorityKernelTest.sign(q.device.getPrivate(),c.signingBytes())));}
 @Test public void failedSignatureSpendsAndCannotRetryDifferentRoute()throws Exception{P p=new P("high");TargetPossessionProof.Challenge c=p.proofs.issue(p.request("root"));assertThrows(GeneralSecurityException.class,()->p.proofs.verify(c,CurrentAuthorityKernelTest.sign(p.f.root.getPrivate(),c.signingBytes())));assertThrows(SecurityException.class,()->p.proofs.verify(c,CurrentAuthorityKernelTest.sign(p.device.getPrivate(),c.signingBytes())));}
 @Test public void staleSourceOrWrongRequestCannotConsumePositiveReceipt()throws Exception{P p=new P("high");AdminProofVerifier.KeyProof r=p.request("root");TargetPossessionProof.Challenge c=p.proofs.issue(r);TargetPossessionProof.Receipt receipt=p.proofs.verify(c,CurrentAuthorityKernelTest.sign(p.device.getPrivate(),c.signingBytes()));assertThrows(SecurityException.class,()->p.proofs.consume(receipt,p.request("root")));}
 @Test public void possessionHasRealDeadlineAndSourceIncarnationFence()throws Exception{P p=new P("high");TargetPossessionProof.Challenge c=p.proofs.issue(p.request("root"));p.f.time.set(30_010);assertThrows(SecurityException.class,()->p.proofs.verify(c,CurrentAuthorityKernelTest.sign(p.device.getPrivate(),c.signingBytes())));P q=new P("high");TargetPossessionProof.Challenge d=q.proofs.issue(q.request("root"));q.f.incarnation.set(new Object());assertThrows(SecurityException.class,()->q.proofs.verify(d,CurrentAuthorityKernelTest.sign(q.device.getPrivate(),d.signingBytes())));}
 @Test public void compiledDevicesRejectNonHighestOwnerAndDuplicatePairs()throws Exception{P p=new P("high");DeviceWhitelist.Device d=new DeviceWhitelist.Device("high",p.device.getPublic().getEncoded());assertThrows(IllegalArgumentException.class,()->new DeviceWhitelist(p.f.compiled,d,d));assertThrows(IllegalArgumentException.class,()->new DeviceWhitelist(p.f.compiled,new DeviceWhitelist.Device("low",p.device.getPublic().getEncoded())));}
}
